// Validate API Response
const response = $input.all()[0].json;

// Check if response exists
if (!response) {
  console.error('No response from Finnhub API');
  return [{
    json: {
      hasData: false,
      error: 'No response from Finnhub API',
      data: [],
      message: 'API request failed'
    }
  }];
}

// Check if data exists and is array
if (!response.data || !Array.isArray(response.data)) {
  console.warn('Invalid API response structure:', JSON.stringify(response).substring(0, 200));
  return [{
    json: {
      hasData: false,
      error: 'Invalid API response structure',
      data: [],
      message: 'Invalid API response from Finnhub'
    }
  }];
}

// Check if data is empty
if (response.data.length === 0) {
  console.log('No insider transactions found in date range');
  return [{
    json: {
      hasData: false,
      error: null,
      data: [],
      message: 'No insider transactions found in the specified date range'
    }
  }];
}

// Return valid data
console.log(`Successfully fetched ${response.data.length} transactions`);
return [{
  json: {
    hasData: true,
    error: null,
    data: response.data,
    count: response.data.length,
    message: 'Data fetched successfully',
    fetchedAt: new Date().toISOString()
  }
}];

// Process and Analyze Transactions
const input = $input.all()[0].json;

if (!input.hasData || !input.data || input.data.length === 0) {
  console.log('No transactions to process');
  return [];
}

const transactions = input.data;
console.log('Processing', transactions.length, 'transactions');

// Group transactions by symbol and calculate net insider activity
const stockActivity = {};

transactions.forEach(transaction => {
  const symbol = transaction.symbol || 'N/A';

  if (symbol === 'N/A' || !symbol) {
    return;
  }

  const shares = Math.abs(parseFloat(transaction.share) || 0);
  const price = parseFloat(transaction.transactionPrice) || 0;
  const transactionValue = shares * price;
  const netChange = parseFloat(transaction.change) || 0;
  const isBuy = netChange > 0;
  const isSell = netChange < 0;

  // Initialize stock if not exists
  if (!stockActivity[symbol]) {
    stockActivity[symbol] = {
      symbol: symbol,
      netMoneyFlow: 0,
      netSharesChange: 0,
      totalInsiders: 0,
      buyersCount: 0,
      sellersCount: 0,
      transactions: [],
      insiders: {}
    };
  }

  const stock = stockActivity[symbol];

  // Calculate net money flow
  if (isBuy) {
    stock.netMoneyFlow += transactionValue;
    stock.netSharesChange += shares;
    stock.buyersCount++;
  } else if (isSell) {
    stock.netMoneyFlow -= transactionValue;
    stock.netSharesChange -= shares;
    stock.sellersCount++;
  }

  // Track individual insider
  const insiderName = transaction.name || 'Unknown';
  if (!stock.insiders[insiderName]) {
    stock.insiders[insiderName] = {
      name: insiderName,
      totalBuyValue: 0,
      totalSellValue: 0,
      buyCount: 0,
      sellCount: 0,
      netValue: 0
    };
    stock.totalInsiders++;
  }

  const insider = stock.insiders[insiderName];
  if (isBuy) {
    insider.totalBuyValue += transactionValue;
    insider.buyCount++;
  } else if (isSell) {
    insider.totalSellValue += transactionValue;
    insider.sellCount++;
  }
  insider.netValue = insider.totalBuyValue - insider.totalSellValue;

  // Store transaction details
  stock.transactions.push({
    date: transaction.transactionDate,
    insiderName: insiderName,
    shares: shares,
    price: price,
    value: transactionValue,
    type: isBuy ? 'BUY' : isSell ? 'SELL' : 'OTHER',
    netChange: netChange,
    filingDate: transaction.filingDate || ''
  });
});

// Convert to array and analyze
const analyzedStocks = Object.values(stockActivity)
  .filter(stock => Math.abs(stock.netMoneyFlow) > 0)
  .map(stock => {
    const netFlow = stock.netMoneyFlow;
    const absFlow = Math.abs(netFlow);
    const flowMM = absFlow / 1000000;

    // Determine activity type
    let activityType = 'NO NET ACTIVITY';
    if (netFlow > 0) activityType = 'NET BUYING';
    else if (netFlow < 0) activityType = 'NET SELLING';

    // Generate recommendation
    let recommendation = 'HOLD';
    let confidence = 'LOW';

    if (absFlow > 5000000) {
      recommendation = netFlow > 0 ? '🚀 STRONG BUY' : '⚠️ CAUTION';
      confidence = 'HIGH';
    } else if (absFlow > 1000000) {
      recommendation = netFlow > 0 ? '📈 BUY' : '👀 MONITOR';
      confidence = 'MEDIUM';
    } else if (absFlow > 100000) {
      recommendation = '📊 HOLD';
      confidence = 'LOW';
    }

    // Top insiders
    const topInsiders = Object.values(stock.insiders)
      .sort((a, b) => Math.abs(b.netValue) - Math.abs(a.netValue))
      .slice(0, 5)
      .map(insider => ({
        name: insider.name,
        netValue: insider.netValue,
        netValueFormatted: `$${(Math.abs(insider.netValue) / 1000000).toFixed(2)}M`,
        activity: insider.netValue > 0 ? 'BUYING' : insider.netValue < 0 ? 'SELLING' : 'NEUTRAL',
        buyCount: insider.buyCount,
        sellCount: insider.sellCount
      }));

    return {
      symbol: stock.symbol,
      netMoneyFlow: netFlow,
      netMoneyFlowFormatted: `$${flowMM.toFixed(2)}M ${netFlow >= 0 ? '(BUY)' : '(SELL)'}`,
      netSharesChange: stock.netSharesChange,
      activityType: activityType,
      totalInsiders: stock.totalInsiders,
      buyersCount: stock.buyersCount,
      sellersCount: stock.sellersCount,
      recommendation: recommendation,
      confidence: confidence,
      topInsiders: topInsiders,
      transactionCount: stock.transactions.length,
      transactions: stock.transactions,
      analysisDate: new Date().toISOString().split('T')[0],
      analysisTimestamp: new Date().toISOString()
    };
  })
  .sort((a, b) => Math.abs(b.netMoneyFlow) - Math.abs(a.netMoneyFlow));

console.log('Analyzed', analyzedStocks.length, 'stocks with insider activity');

if (analyzedStocks.length === 0) {
  return [];
}

return analyzedStocks.map(stock => ({ json: stock }));

// Log No Data
console.log('No insider trading data to process');

const input = $input.all()[0].json;

return [{
  json: {
    status: 'no_data',
    message: input.message || 'No insider transactions found',
    executionId: $('Get Environment Variables').item.json.executionId,
    timestamp: new Date().toISOString()
  }
}];
